// AUTO-GENERATED, committed on purpose. Base64 data-URI @font-face rules for the
// frame packs' DISPLAY faces, so scene-kit renders each pack in its real display
// font deterministically (no @fontsource runtime dep, no network, no file server).
// Source: @fontsource/* woff2 (OFL-licensed). Regenerate via scratchpad/gen-font-module.js.
// Each face is declared over font-weight:1 1000 so any heading weight maps to the
// single bundled file. Total inlined: ~193KB base64.
//
// SYSTEM/SAFE display faces (Inter, Georgia) are intentionally ABSENT — the
// renderer already resolves them; only true webfonts need inlining here.

const FONT_FACES = {
  "Space Grotesk": "@font-face{font-family:'Space Grotesk';font-style:normal;font-weight:1 1000;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}",
  "Archivo Black": "@font-face{font-family:'Archivo Black';font-style:normal;font-weight:1 1000;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}",
  "Instrument Serif": "@font-face{font-family:'Instrument Serif';font-style:normal;font-weight:1 1000;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}",
  "Bricolage Grotesque": "@font-face{font-family:'Bricolage Grotesque';font-style:normal;font-weight:1 1000;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}",
  "Anton": "@font-face{font-family:'Anton';font-style:normal;font-weight:1 1000;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}",
  "Fraunces": "@font-face{font-family:'Fraunces';font-style:normal;font-weight:1 1000;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}",
  "JetBrains Mono": "@font-face{font-family:'JetBrains Mono';font-style:normal;font-weight:1 1000;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}",
  "IBM Plex Mono": "@font-face{font-family:'IBM Plex Mono';font-style:normal;font-weight:1 1000;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}"
};

// Concatenated @font-face CSS for a display family, or "" if it needs none
// (system/safe font) or isn't bundled. Case-insensitive on the family name.
function fontFaceCss(family) {
  if (!family) return "";
  const key = Object.keys(FONT_FACES).find((k) => k.toLowerCase() === String(family).toLowerCase().trim());
  return key ? FONT_FACES[key] : "";
}

// Whether a display family is a bundled webfont (has an inlined @font-face).
function isBundled(family) { return !!fontFaceCss(family); }

module.exports = { FONT_FACES, fontFaceCss, isBundled };
